cat >> test/reports.test.js << 'EOFTEST'

test('lateFee returns 0 for invoice not yet due', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const r = require('../src/reports.js');

  const fee = r.lateFee(invoice, invoice.dueDate);
  assert.equal(fee, 0);
});

test('lateFee returns 0 for invoice due on asOf date', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const r = require('../src/reports.js');

  const fee = r.lateFee(invoice, invoice.dueDate);
  assert.equal(fee, 0);
});

test('lateFee calculates fee for 1 day overdue', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const r = require('../src/reports.js');
  const totals = invoiceTotals(invoice);

  const fee = r.lateFee(invoice, '2024-02-01');
  const expectedFee = Math.round(totals.total * 0.0004 * 1);
  assert.equal(fee, expectedFee);
});

test('lateFee calculates fee for multiple days overdue', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const r = require('../src/reports.js');
  const totals = invoiceTotals(invoice);

  const fee = r.lateFee(invoice, '2024-02-10');
  const expectedFee = Math.round(totals.total * 0.0004 * 10);
  assert.equal(fee, expectedFee);
});

test('lateFee is 0.04% per day', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const r = require('../src/reports.js');
  const totals = invoiceTotals(invoice);

  const fee1Day = r.lateFee(invoice, '2024-02-01');
  const fee2Days = r.lateFee(invoice, '2024-02-02');

  assert.equal(fee2Days - fee1Day, Math.round(totals.total * 0.0004));
});

test('lateFee returns 0 for paid invoice', () => {
  let invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const totals = invoiceTotals(invoice);
  const payment = recordPayment(invoice, { amount: totals.total, date: '2024-01-20' });
  invoice = payment.value;

  const r = require('../src/reports.js');
  const fee = r.lateFee(invoice, '2024-02-10');
  assert.equal(fee, 0);
});

test('lateFee calculates on remaining balance for partially paid invoice', () => {
  let invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const totals = invoiceTotals(invoice);
  const halfPayment = Math.floor(totals.total / 2);
  const payment = recordPayment(invoice, { amount: halfPayment, date: '2024-01-20' });
  invoice = payment.value;

  const r = require('../src/reports.js');
  const fee = r.lateFee(invoice, '2024-02-10');
  const remaining = totals.total - halfPayment;
  const expectedFee = Math.round(remaining * 0.0004 * 10);
  assert.equal(fee, expectedFee);
});

test('lateFee returns 0 for invalid asOf date', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const r = require('../src/reports.js');

  const fee = r.lateFee(invoice, 'not-a-date');
  assert.equal(fee, 0);
});

test('lateFee returns 0 for negative days overdue', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const r = require('../src/reports.js');

  const fee = r.lateFee(invoice, '2024-01-10');
  assert.equal(fee, 0);
});

test('lateFee is integer cents', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const r = require('../src/reports.js');

  const fee = r.lateFee(invoice, '2024-02-05');
  assert.equal(Number.isInteger(fee), true);
});

test('lateFee never returns negative', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const r = require('../src/reports.js');

  const fee = r.lateFee(invoice, '2024-02-10');
  assert.equal(fee >= 0, true);
});

test('lateFee scales with invoice amount', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2024-01-01', [{ sku: 'DES-HOUR', qty: 1 }]);
  const invoice2 = createAndIssueInvoice('C-001', '2024-01-02', [{ sku: 'DES-HOUR', qty: 2 }]);

  const r = require('../src/reports.js');
  const fee1 = r.lateFee(invoice1, '2024-02-10');
  const fee2 = r.lateFee(invoice2, '2024-02-10');

  assert.equal(fee2, fee1 * 2);
});

test('lateFee with 30 day threshold', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const r = require('../src/reports.js');
  const totals = invoiceTotals(invoice);

  const fee30Days = r.lateFee(invoice, '2024-03-02');
  const expectedFee = Math.round(totals.total * 0.0004 * 30);
  assert.equal(fee30Days, expectedFee);
});

test('lateFee does not mutate invoice', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const originalStatus = invoice.status;
  const originalDueDate = invoice.dueDate;
  const r = require('../src/reports.js');

  r.lateFee(invoice, '2024-02-10');

  assert.equal(invoice.status, originalStatus);
  assert.equal(invoice.dueDate, originalDueDate);
});

test('lateFee with invoice having voucher', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  if (!r.ok) throw new Error('Failed to create invoice');

  let invoice = r.value;
  const applyResult = require('../src/invoices.js').applyVoucher(invoice, { code: 'SAVE10', amount: 1000 });
  if (!applyResult.ok) throw new Error('Failed to apply voucher');
  invoice = applyResult.value;

  const issued = issueInvoice(invoice, []);
  if (!issued.ok) throw new Error('Failed to issue invoice');
  invoice = issued.value;

  const reports = require('../src/reports.js');
  const totals = invoiceTotals(invoice);
  const fee = reports.lateFee(invoice, '2024-02-10');
  const expectedFee = Math.round(totals.total * 0.0004 * 10);
  assert.equal(fee, expectedFee);
});
EOFTEST

