import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { overdueInvoices, vatSummary, lateFee } from '../src/reports.js';

function createAndIssueInvoice(customerId, issueDate, lines = [{ sku: 'DES-HOUR', qty: 2 }], terms = 'NET30') {
  const r = createInvoice({
    customerId,
    issueDate,
    lines,
    terms,
  });
  if (!r.ok) throw new Error('Failed to create invoice');
  const issued = issueInvoice(r.value, []);
  if (!issued.ok) throw new Error('Failed to issue invoice');
  return issued.value;
}

test('overdueInvoices returns empty array when no invoices', () => {
  const r = overdueInvoices([], '2024-12-31');
  assert.equal(r.ok, true);
  assert.deepEqual(r.value, []);
});

test('overdueInvoices returns empty array when all invoices are paid', () => {
  let invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const totals = invoiceTotals(invoice);
  const payment = recordPayment(invoice, { amount: totals.total, date: '2024-02-15' });
  invoice = payment.value;

  const r = overdueInvoices([invoice], '2024-12-31');
  assert.equal(r.ok, true);
  assert.deepEqual(r.value, []);
});

test('overdueInvoices returns empty array when no invoices past due date', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-12-01');
  const r = overdueInvoices([invoice], '2024-12-15');
  assert.equal(r.ok, true);
  assert.deepEqual(r.value, []);
});

test('overdueInvoices includes issued invoices past due date', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const totals = invoiceTotals(invoice);
  const r = overdueInvoices([invoice], '2024-02-15');

  assert.equal(r.ok, true);
  assert.equal(r.value.length, 1);
  assert.equal(r.value[0].number, invoice.number);
  assert.equal(r.value[0].customerId, 'C-001');
  assert.equal(r.value[0].dueDate, invoice.dueDate);
  assert.equal(r.value[0].due, totals.total);
  assert.equal(r.value[0].daysOverdue > 0, true);
});

test('overdueInvoices includes partially_paid invoices past due date', () => {
  let invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const totals = invoiceTotals(invoice);
  const payment = recordPayment(invoice, { amount: Math.floor(totals.total / 2), date: '2024-01-20' });
  invoice = payment.value;

  const r = overdueInvoices([invoice], '2024-02-15');

  assert.equal(r.ok, true);
  assert.equal(r.value.length, 1);
  assert.equal(r.value[0].due, Math.ceil(totals.total / 2));
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const r = overdueInvoices([invoice], '2024-02-10');

  assert.equal(r.ok, true);
  assert.equal(r.value[0].daysOverdue, 10);
});

test('overdueInvoices excludes draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  if (!r.ok) throw new Error('Failed to create invoice');
  const draft = r.value;

  const result = overdueInvoices([draft], '2024-02-15');
  assert.equal(result.ok, true);
  assert.deepEqual(result.value, []);
});

test('overdueInvoices excludes paid invoices', () => {
  let invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const totals = invoiceTotals(invoice);
  const payment = recordPayment(invoice, { amount: totals.total, date: '2024-02-15' });
  invoice = payment.value;

  const r = overdueInvoices([invoice], '2024-12-31');
  assert.equal(r.ok, true);
  assert.deepEqual(r.value, []);
});

test('overdueInvoices sorts by daysOverdue descending (most overdue first)', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2024-01-01');
  const invoice2 = createAndIssueInvoice('C-001', '2024-01-15');
  const invoice3 = createAndIssueInvoice('C-001', '2024-01-20');

  const r = overdueInvoices([invoice3, invoice1, invoice2], '2024-02-25');

  assert.equal(r.ok, true);
  assert.equal(r.value.length, 3);
  assert.equal(r.value[0].number, invoice1.number);
  assert.equal(r.value[1].number, invoice2.number);
  assert.equal(r.value[2].number, invoice3.number);
});

test('overdueInvoices handles mixed customer IDs', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2024-01-01');
  const invoice3 = createAndIssueInvoice('C-001', '2024-01-10');
  const invoice2 = createAndIssueInvoice('C-002', '2024-01-20');

  const r = overdueInvoices([invoice1, invoice2, invoice3], '2024-02-25');

  assert.equal(r.ok, true);
  assert.equal(r.value.length, 3);
  assert.equal(r.value[0].customerId, 'C-001');
  assert.equal(r.value[1].customerId, 'C-001');
  assert.equal(r.value[2].customerId, 'C-002');
});

test('overdueInvoices returns error for invalid date', () => {
  const r = overdueInvoices([], 'not-a-date');
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('overdueInvoices returns error for date in wrong format', () => {
  const r = overdueInvoices([], '12/31/2024');
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('overdueInvoices handles edge case when invoice dueDate equals asOf (not overdue)', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const r = overdueInvoices([invoice], invoice.dueDate);

  assert.equal(r.ok, true);
  assert.deepEqual(r.value, []);
});

test('overdueInvoices with multiple payments on partially_paid invoice', () => {
  let invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const totals = invoiceTotals(invoice);

  let payment1 = recordPayment(invoice, { amount: 1000, date: '2024-01-20' });
  invoice = payment1.value;

  let payment2 = recordPayment(invoice, { amount: 2000, date: '2024-02-01' });
  invoice = payment2.value;

  const r = overdueInvoices([invoice], '2024-02-15');

  assert.equal(r.ok, true);
  assert.equal(r.value.length, 1);
  assert.equal(r.value[0].due, totals.total - 3000);
});

test('overdueInvoices does not mutate input invoices', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const originalNumber = invoice.number;
  const originalCustomerId = invoice.customerId;

  overdueInvoices([invoice], '2024-02-15');

  assert.equal(invoice.number, originalNumber);
  assert.equal(invoice.customerId, originalCustomerId);
});

test('overdueInvoices does not mutate invoices array', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2024-01-01');
  const invoice2 = createAndIssueInvoice('C-002', '2024-01-15');
  const invoices = [invoice1, invoice2];
  const originalLength = invoices.length;

  overdueInvoices(invoices, '2024-02-15');

  assert.equal(invoices.length, originalLength);
  assert.equal(invoices[0], invoice1);
  assert.equal(invoices[1], invoice2);
});

test('overdueInvoices with NET14 terms', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-01-01', [{ sku: 'DES-HOUR', qty: 2 }], 'NET14');
  const r = overdueInvoices([invoice], '2024-01-20');

  assert.equal(r.ok, true);
  assert.equal(r.value.length, 1);
  assert.equal(r.value[0].dueDate, '2024-01-15');
});

test('overdueInvoices with EOM terms', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-01-15', [{ sku: 'DES-HOUR', qty: 2 }], 'EOM');
  const r = overdueInvoices([invoice], '2024-02-05');

  assert.equal(r.ok, true);
  assert.equal(r.value.length, 1);
  assert.equal(r.value[0].dueDate, '2024-01-31');
});
test('vatSummary returns empty array for no invoices', () => {
  const r = vatSummary([]);
  assert.equal(r.ok, true);
  assert.deepEqual(r.value, []);
});

test('vatSummary excludes draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  if (!r.ok) throw new Error('Failed to create invoice');
  const draft = r.value;

  const result = vatSummary([draft]);
  assert.equal(result.ok, true);
  assert.deepEqual(result.value, []);
});

test('vatSummary includes issued invoices', () => {
  const invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const r = vatSummary([invoice]);

  assert.equal(r.ok, true);
  assert.equal(r.value.length, 1);
  assert.equal(r.value[0].rate, 21);
  assert.equal(typeof r.value[0].base, 'number');
  assert.equal(typeof r.value[0].vat, 'number');
  assert.equal(r.value[0].vat > 0, true);
});

test('vatSummary includes partially_paid invoices', () => {
  let invoice = createAndIssueInvoice('C-001', '2024-01-01');
  const totals = invoiceTotals(invoice);
  const payment = recordPayment(invoice, { amount: Math.floor(totals.total / 2), date: '2024-01-20' });
  invoice = payment.value;

