  const invoice2 = createAndIssueInvoice('C-001', '2024-01-02', [{ sku: 'PRINT-A4', qty: 1 }]);

  const r = vatSummary([invoice1, invoice2]);

  assert.equal(r.ok, true);
  assert.equal(r.value.length, 2);
  const rates = r.value.map(s => s.rate).sort((a, b) => b - a);
  assert.equal(rates[0], 21);
  assert.equal(rates[1], 9);
});

