import { ok, fail } from './result.js';
import { daysBetween, isValidDate } from './dates.js';
import { balanceDue } from './payments.js';
import { lineDiscount, lineVat } from './invoices.js';
import { roundCents } from './money.js';

/**
 * Generate a report of invoices past their due date.
 * @param {Array<{ number?: string, customerId: string, dueDate: string, status: string, payments?: Array<any> }>} invoices all invoices to filter
 * @param {string} asOf date in YYYY-MM-DD format (report cutoff date)
 * @returns {{ ok: true, value: Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }> } | { ok: false, error: string }}
 */
export function overdueInvoices(invoices, asOf) {
  if (!isValidDate(asOf)) {
    return fail('DATE_INVALID');
  }

  const overdue = invoices
    .filter(inv => (inv.status === 'issued' || inv.status === 'partially_paid') && inv.dueDate < asOf)
    .map(inv => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return ok(overdue);
}

/**
 * Generate a VAT summary grouped by tax rate.
 * @param {Array<{ status: string, lines: Array<{ vatRate: number, qty: number, unitPrice: number, discountPercent?: number }> }>} invoices all invoices to analyze
 * @returns {{ ok: true, value: Array<{ rate: number, base: number, vat: number }> }} sorted by rate descending
 */
export function vatSummary(invoices) {
  const byRate = {};

  invoices
    .filter(inv => inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid')
    .forEach(inv => {
      inv.lines.forEach(line => {
        const rate = line.vatRate;
        const base = Math.max(0, line.qty * line.unitPrice - lineDiscount(line));
        const vat = lineVat(line);

        if (!byRate[rate]) {
          byRate[rate] = { rate, base: 0, vat: 0 };
        }
        byRate[rate].base += base;
        byRate[rate].vat += vat;
      });
    });

  const summary = Object.values(byRate).sort((a, b) => b.rate - a.rate);
  return ok(summary);
}

/**
 * Calculate late fee for an invoice.
 * @param {Object} invoice the invoice to check
 * @param {string} asOf date in YYYY-MM-DD format (check date)
 * @returns {number} late fee in integer cents (0.04% per day × days overdue × amount due)
 */
export function lateFee(invoice, asOf) {
  if (!isValidDate(asOf)) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  if (daysOverdue <= 0) {
    return 0;
  }

  const due = balanceDue(invoice);
  const fee = due * 0.0004 * daysOverdue;
  return roundCents(fee);
}

